import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/getisord/getisord_no2_Q1_2021.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Calculate the citywide average NO2 value
citywide_avg = data['avg_no2_value'].mean()

# Impute missing values with the citywide average
data['avg_no2_value'] = data['avg_no2_value'].fillna(citywide_avg)

# Define neighborhood relationships
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the combined NO2 value for each local area
combined_values = {}
for index, row in data.iterrows():
    local_area = [row['borough']]
    for neighbor in neighborhoods[row['borough']]:
        local_area.append(data[data['borough'] == neighbor]['avg_no2_value'].values[0])
    combined_values[row['borough']] = np.sum(local_area)

# Apply the Getis-Ord Gi* method
z_scores = {}
for index, row in data.iterrows():
    if np.isnan(row['avg_no2_value']):
        continue
    local_area = [row['avg_no2_value']]
    for neighbor in neighborhoods[row['borough']]:
        local_area.append(data[data['borough'] == neighbor]['avg_no2_value'].values[0])
    local_area = np.array(local_area)
    mean = np.mean(local_area)
    std_dev = np.std(local_area)
    z = (local_area - mean) / std_dev
    z_scores[row['borough']] = z

# Identify hot and cold spots
hot_cold = []
for borough, z in z_scores.items():
    if np.abs(z) > 1.96:
        hot_cold.append((borough, 'HOT', z))
    elif np.abs(z) > 2.576:
        hot_cold.append((borough, 'COLD', z))

# Report the results
data_points_used = len(data) - data['avg_no2_value'].isnull().sum()
print(f"data_points_used = {data_points_used}")
if len(hot_cold) == 0:
    print("FINAL ANSWER: none")
else:
    print(f"FINAL ANSWER: {', '.join([f'{borough} ({stat}, z-score = {z:.2f})' for borough, stat, z in hot_cold])}")
